"""Sales summary over paid orders, as text or CSV."""

import csv
import io

from .money import fmt_cents
from .pricing import line_total


def sales_summary(orders):
    """Totals over paid orders: order count, units, revenue, and per-SKU units/revenue."""
    summary = {"orders": 0, "units": 0, "revenue_cents": 0, "by_sku": {}}
    for order in orders:
        if order.status != "paid":
            continue
        summary["orders"] += 1
        for item in order.items:
            row = summary["by_sku"].setdefault(item.sku, {"units": 0, "revenue_cents": 0})
            amount = line_total(item)
            row["units"] += item.quantity
            row["revenue_cents"] += amount
            summary["units"] += item.quantity
            summary["revenue_cents"] += amount
    return summary


def render_text(summary, catalog):
    """Human-readable report."""
    lines = [
        "Orders: %d" % summary["orders"],
        "Units: %d" % summary["units"],
        "Revenue: %s" % fmt_cents(summary["revenue_cents"]),
    ]
    for sku in sorted(summary["by_sku"]):
        row = summary["by_sku"][sku]
        name = catalog[sku].name if sku in catalog else sku
        lines.append("  %-8s %-20s %4d  %10s" % (sku, name, row["units"], fmt_cents(row["revenue_cents"])))
    return "\n".join(lines) + "\n"


def render_csv(summary, catalog):
    """CSV with one row per SKU."""
    out = io.StringIO()
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(["sku", "name", "category", "units", "revenue"])
    for sku in sorted(summary["by_sku"]):
        row = summary["by_sku"][sku]
        product = catalog.get(sku)
        writer.writerow([
            sku,
            product.name if product else "",
            (product.category or "") if product else "",
            row["units"],
            fmt_cents(row["revenue_cents"]),
        ])
    return out.getvalue()
"""JSON files for the catalog, orders and inventory."""

import json

from .errors import StorageError
from .inventory import Inventory
from .models import LineItem, Order, Product


def _read(path):
    try:
        with open(path) as f:
            return json.load(f)
    except (OSError, ValueError) as e:
        raise StorageError("%s: %s" % (path, e)) from None


def _write(path, data):
    with open(path, "w") as f:
        json.dump(data, f, indent=2, sort_keys=True)
        f.write("\n")


def load_catalog(path):
    """Return {sku: Product}."""
    return {
        p["sku"]: Product(p["sku"], p["name"], p["price_cents"], category=p.get("category"))
        for p in _read(path)
    }


def save_catalog(path, catalog):
    """Write {sku: Product} to path."""
    _write(path, [
        {"sku": p.sku, "name": p.name, "price_cents": p.price_cents, "category": p.category}
        for p in catalog.values()
    ])


def load_orders(path):
    """Return a list of Order."""
    orders = []
    for o in _read(path):
        items = [LineItem(i["sku"], i["quantity"], i["unit_price_cents"]) for i in o["items"]]
        orders.append(Order(o["id"], o["customer"], o["created_at"], items, o["status"], o["total_cents"]))
    return orders


def save_orders(path, orders):
    """Write a list of Order to path."""
    _write(path, [
        {
            "id": o.id,
            "customer": o.customer,
            "created_at": o.created_at,
            "items": [
                {"sku": i.sku, "quantity": i.quantity, "unit_price_cents": i.unit_price_cents}
                for i in o.items
            ],
            "status": o.status,
            "total_cents": o.total_cents,
        }
        for o in orders
    ])


def load_inventory(path):
    """Return an Inventory."""
    return Inventory.from_dict(_read(path))


def save_inventory(path, inventory):
    """Write an Inventory to path."""
    _write(path, inventory.to_dict())

